function fmt(n: number) {
  const abs = Math.abs(n);
  if (abs >= 1000000) return `${n < 0 ? "-" : ""}$${(abs / 1000000).toFixed(2)}M`;
  if (abs >= 1000) return `${n < 0 ? "-" : ""}$${(abs / 1000).toFixed(1)}K`;
  return `${n < 0 ? "-" : ""}$${Math.round(abs).toLocaleString()}`;
}
